CREATE OR REPLACE FUNCTION public._festival_edition_ticket_plan_result(
  p_festival_company_id uuid,
  p_festival_edition_id uuid
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT jsonb_build_object(
    'festivalCompanyId', company.id,
    'festivalName', edition.name,
    'festivalDates', (
      SELECT coalesce(jsonb_agg(day::date ORDER BY day), '[]'::jsonb)
      FROM generate_series(edition.starts_on, edition.ends_on, interval '1 day') day
    ),
    'usableSiteCapacity', site.usable_capacity,
    'sitePlanStatus', site.status,
    'ticketPlan', CASE WHEN ticket.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', ticket.id,
      'currencyCode', ticket.currency_code,
      'salesTaxRateBasisPoints', ticket.sales_tax_rate_basis_points,
      'bookingFeeMode', ticket.booking_fee_mode,
      'bookingFeeMinor', ticket.booking_fee_minor,
      'bookingFeeBasisPoints', ticket.booking_fee_basis_points,
      'bookingFeePayer', ticket.booking_fee_payer,
      'refundPolicy', coalesce(ticket.refund_policy, ''),
      'transferPolicy', coalesce(ticket.transfer_policy, ''),
      'minimumPurchaseQuantity', ticket.minimum_purchase_quantity,
      'maximumPurchaseQuantity', ticket.maximum_purchase_quantity,
      'expectedSellThroughBasisPoints', ticket.expected_sell_through_basis_points,
      'expectedRefundBasisPoints', ticket.expected_refund_basis_points,
      'expectedComplimentaryUseBasisPoints', ticket.expected_complimentary_use_basis_points,
      'expectedNoShowBasisPoints', ticket.expected_no_show_basis_points,
      'status', ticket.status
    ) END,
    'products', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', product.id,
        'name', product.name,
        'slug', product.slug,
        'ticketType', product.ticket_type,
        'productClass', product.product_class,
        'accessScope', product.access_scope,
        'validFromDate', product.valid_from_date,
        'validToDate', product.valid_to_date,
        'priceMinor', product.price_minor,
        'faceValueMinor', product.face_value_minor,
        'capacityLimit', product.capacity_limit,
        'minimumAge', product.minimum_age,
        'includesCamping', product.includes_camping,
        'includesParking', product.includes_parking,
        'includesVipArea', product.includes_vip_area,
        'includesBackstage', product.includes_backstage,
        'transferable', product.transferable,
        'refundable', product.refundable,
        'salePriority', product.sale_priority,
        'active', product.active
      ) ORDER BY product.sale_priority)
      FROM public.festival_ticket_products product
      WHERE product.festival_ticket_plan_id = ticket.id
    ), '[]'::jsonb),
    'releasePhases', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', phase.id,
        'productId', phase.festival_ticket_product_id,
        'name', phase.name,
        'releaseType', phase.release_type,
        'sortOrder', phase.sort_order,
        'startsAt', phase.starts_at,
        'endsAt', phase.ends_at,
        'allocationLimit', phase.allocation_limit,
        'priceOverrideMinor', phase.price_override_minor,
        'discountBasisPoints', phase.discount_basis_points,
        'eligibilityRule', coalesce(phase.eligibility_rule, ''),
        'status', phase.status
      ) ORDER BY phase.sort_order)
      FROM public.festival_ticket_release_phases phase
      WHERE phase.festival_ticket_plan_id = ticket.id
    ), '[]'::jsonb),
    'capacityAllocations', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', allocation.id,
        'productId', allocation.festival_ticket_product_id,
        'productSlug', product.slug,
        'festivalDate', allocation.festival_date,
        'capacityAllocated', allocation.capacity_allocated,
        'capacityReserved', allocation.capacity_reserved,
        'capacityComplimentary', allocation.capacity_complimentary
      ) ORDER BY allocation.festival_date, product.sale_priority)
      FROM public.festival_ticket_capacity_allocations allocation
      JOIN public.festival_ticket_products product
        ON product.id = allocation.festival_ticket_product_id
      WHERE allocation.festival_ticket_plan_id = ticket.id
    ), '[]'::jsonb),
    'forecast', coalesce(ticket.forecast, '{}'::jsonb),
    'issues', coalesce(ticket.validation_issues, '[]'::jsonb),
    'warnings', '[]'::jsonb,
    'ready', coalesce(ticket.status = 'ready_for_artist_planning', false),
    'canWrite', edition.status NOT IN ('completed', 'cancelled') AND edition.locked_at IS NULL,
    'planningVersion', coalesce(ticket.planning_version, 0),
    'updatedAt', ticket.updated_at
  )
  FROM public.festival_companies company
  JOIN public.festival_editions_v2 edition
    ON edition.festival_company_id = company.id
   AND edition.id = p_festival_edition_id
  JOIN public.festival_site_plans site
    ON site.festival_edition_id = edition.id
  LEFT JOIN public.festival_ticket_plans ticket
    ON ticket.festival_edition_id = edition.id
  WHERE company.id = p_festival_company_id
$$;

