CREATE OR REPLACE FUNCTION public.save_festival_edition_ticket_plan(
  p_festival_company_id uuid,
  p_festival_edition_id uuid,
  p_expected_version integer,
  p_ticket_plan jsonb,
  p_products jsonb,
  p_release_phases jsonb,
  p_capacity_allocations jsonb,
  p_idempotency_key uuid,
  p_complete boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor uuid := public._caller_profile_id();
  edition public.festival_editions_v2%ROWTYPE;
  site public.festival_site_plans%ROWTYPE;
  ticket public.festival_ticket_plans%ROWTYPE;
  request public.festival_ticket_plan_requests%ROWTYPE;
  admission jsonb;
  product_id uuid;
  payload_hash text;
  response jsonb;
  price_minor bigint;
  capacity integer;
  sell_through integer;
  projection_forecast jsonb;
BEGIN
  IF auth.uid() IS NULL
     OR actor IS NULL
     OR NOT public._festival_projection_authorized(
       p_festival_company_id,
       p_festival_edition_id,
       actor
     ) THEN
    RAISE EXCEPTION 'festival_ticket_plan_forbidden' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO edition
  FROM public.festival_editions_v2
  WHERE id = p_festival_edition_id
    AND festival_company_id = p_festival_company_id
  FOR UPDATE;
  IF edition.status IN ('completed', 'cancelled') OR edition.locked_at IS NOT NULL THEN
    RAISE EXCEPTION 'festival_ticket_plan_locked' USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.materialize_festival_edition_foundations(
    p_festival_company_id,
    p_festival_edition_id
  );

  SELECT * INTO site
  FROM public.festival_site_plans
  WHERE festival_edition_id = edition.id;
  SELECT * INTO ticket
  FROM public.festival_ticket_plans
  WHERE festival_edition_id = edition.id
  FOR UPDATE;

  IF site.id IS NULL OR ticket.id IS NULL OR site.status <> 'ready_for_ticketing' THEN
    RAISE EXCEPTION 'festival_site_plan_incomplete' USING ERRCODE = 'P0001';
  END IF;

  SELECT value INTO admission
  FROM jsonb_array_elements(coalesce(p_products, '[]'::jsonb)) value
  WHERE value->>'productClass' = 'admission'
    AND coalesce((value->>'active')::boolean, true)
  ORDER BY coalesce((value->>'salePriority')::integer, 0)
  LIMIT 1;

  IF admission IS NULL THEN
    RAISE EXCEPTION 'festival_ticket_product_required' USING ERRCODE = 'P0001';
  END IF;

  price_minor := nullif(admission->>'priceMinor', '')::bigint;
  capacity := nullif(admission->>'capacityLimit', '')::integer;
  sell_through := nullif(p_ticket_plan->>'expectedSellThroughBasisPoints', '')::integer;

  IF price_minor IS NULL OR price_minor < 0
     OR capacity IS NULL OR capacity <= 0 OR capacity > site.usable_capacity
     OR sell_through IS NULL OR sell_through NOT BETWEEN 0 AND 10000 THEN
    RAISE EXCEPTION 'festival_ticket_plan_invalid' USING ERRCODE = 'P0001';
  END IF;

  payload_hash := encode(digest(jsonb_build_object(
    'festivalEditionId', edition.id,
    'expectedVersion', p_expected_version,
    'priceMinor', price_minor,
    'capacity', capacity,
    'sellThrough', sell_through,
    'complete', p_complete
  )::text, 'sha256'), 'hex');

  PERFORM pg_advisory_xact_lock(
    hashtextextended(edition.id::text || p_idempotency_key::text, 0)
  );
  SELECT * INTO request
  FROM public.festival_ticket_plan_requests
  WHERE festival_company_id = p_festival_company_id
    AND caller_profile_id = actor
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF request.payload_hash <> payload_hash THEN
      RAISE EXCEPTION 'festival_ticket_plan_idempotency_conflict' USING ERRCODE = 'P0001';
    END IF;
    IF request.status = 'succeeded' THEN
      RETURN request.result;
    END IF;
  ELSE
    INSERT INTO public.festival_ticket_plan_requests(
      festival_company_id,
      caller_profile_id,
      idempotency_key,
      payload_hash
    ) VALUES (
      p_festival_company_id,
      actor,
      p_idempotency_key,
      payload_hash
    ) RETURNING * INTO request;
  END IF;

  IF ticket.planning_version <> p_expected_version THEN
  RAISE EXCEPTION 'festival_ticket_plan_stale' USING ERRCODE = 'P0001';
END IF;

  UPDATE public.festival_ticket_plans
  SET expected_sell_through_basis_points = sell_through,
      status = 'ready_for_artist_planning',
      validation_issues = '[]'::jsonb,
      planning_version = planning_version + 1,
      completed_at = CASE WHEN p_complete THEN now() ELSE completed_at END,
      updated_at = now()
  WHERE id = ticket.id
  RETURNING * INTO ticket;

  INSERT INTO public.festival_ticket_products(
    festival_ticket_plan_id,
    festival_company_id,
    name,
    slug,
    ticket_type,
    product_class,
    access_scope,
    valid_from_date,
    valid_to_date,
    price_minor,
    face_value_minor,
    capacity_limit,
    minimum_age,
    includes_camping,
    includes_parking,
    includes_vip_area,
    includes_backstage,
    transferable,
    refundable,
    sale_priority,
    active
  ) VALUES (
    ticket.id,
    edition.festival_company_id,
    'Standard Festival Ticket',
    'standard-festival-ticket',
    'full_festival',
    'admission',
    'full_festival',
    edition.starts_on,
    edition.ends_on,
    price_minor,
    price_minor,
    capacity,
    NULL,
    false,
    false,
    false,
    false,
    true,
    false,
    0,
    true
  )
  ON CONFLICT (festival_ticket_plan_id, slug)
  DO UPDATE SET
    valid_from_date = EXCLUDED.valid_from_date,
    valid_to_date = EXCLUDED.valid_to_date,
    price_minor = EXCLUDED.price_minor,
    face_value_minor = EXCLUDED.face_value_minor,
    capacity_limit = EXCLUDED.capacity_limit,
    active = true,
    updated_at = now()
  RETURNING id INTO product_id;

  DELETE FROM public.festival_ticket_capacity_allocations
  WHERE festival_ticket_plan_id = ticket.id
    AND festival_ticket_product_id = product_id;
  INSERT INTO public.festival_ticket_capacity_allocations(
    festival_ticket_plan_id,
    festival_ticket_product_id,
    festival_date,
    capacity_allocated,
    capacity_reserved,
    capacity_complimentary
  )
  SELECT ticket.id, product_id, day::date, capacity, 0, 0
  FROM generate_series(edition.starts_on, edition.ends_on, interval '1 day') day;

  projection_forecast := public._festival_projection_forecast(
    edition.starts_on,
    edition.ends_on,
    capacity,
    price_minor,
    sell_through,
    ticket.sales_tax_rate_basis_points,
    ticket.expected_refund_basis_points
  );
  UPDATE public.festival_ticket_plans
  SET forecast = projection_forecast,
      updated_at = now()
  WHERE id = ticket.id;

  response := public._festival_edition_ticket_plan_result(
    p_festival_company_id,
    p_festival_edition_id
  );
  UPDATE public.festival_ticket_plan_requests
  SET status = 'succeeded', result = response, completed_at = now()
  WHERE id = request.id;
  RETURN response;
END;
$$;

CREATE OR REPLACE FUNCTION public._festival_edition_artist_programme_result(
  p_festival_company_id uuid,
  p_festival_edition_id uuid
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT jsonb_build_object(
    'festivalCompanyId', company.id,
    'festivalName', edition.name,
    'festivalDates', (
      SELECT coalesce(jsonb_agg(day::date ORDER BY day), '[]'::jsonb)
      FROM generate_series(edition.starts_on, edition.ends_on, interval '1 day') day
    ),
    'stages', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', stage.id,
        'name', stage.name,
        'stageType', stage.stage_type,
        'capacity', stage.capacity,
        'active', stage.status = 'ready'
      ) ORDER BY stage.sort_order)
      FROM public.festival_site_plan_stages stage
      WHERE stage.festival_site_plan_id = site.id
    ), '[]'::jsonb),
    'programme', CASE WHEN programme.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', programme.id,
      'currencyCode', programme.currency_code,
      'applicationMode', programme.application_mode,
      'applicationsOpenAt', programme.applications_open_at,
      'applicationsCloseAt', programme.applications_close_at,
      'minimumArtistFame', programme.minimum_artist_fame,
      'maximumArtistFame', programme.maximum_artist_fame,
      'preferredGenres', programme.preferred_genres,
      'excludedGenres', programme.excluded_genres,
      'artistBudgetMinor', programme.artist_budget_minor,
      'contingencyBudgetMinor', programme.contingency_budget_minor,
      'minimumPlayerArtistShareBasisPoints', programme.minimum_player_artist_share_basis_points,
      'status', programme.status
    ) END,
    'applicationWindows', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', application_window.id,
        'name', application_window.name,
        'opensAt', application_window.opens_at,
        'closesAt', application_window.closes_at,
        'eligibleArtistType', application_window.eligible_artist_type,
        'minimumFame', application_window.minimum_fame,
        'maximumFame', application_window.maximum_fame,
        'preferredGenres', application_window.preferred_genres,
        'minimumBandMembers', application_window.minimum_band_members,
        'maximumBandMembers', application_window.maximum_band_members,
        'targetStageTypes', application_window.target_stage_types,
        'maximumSetMinutes', application_window.maximum_set_minutes,
        'active', application_window.active
      ) ORDER BY application_window.opens_at)
      FROM public.festival_artist_application_windows application_window
      WHERE application_window.festival_artist_programme_id = programme.id
    ), '[]'::jsonb),
    'applications', '[]'::jsonb,
    'invitations', '[]'::jsonb,
    'offers', '[]'::jsonb,
    'bookings', '[]'::jsonb,
    'budget', jsonb_build_object(
      'artistBudgetMinor', coalesce(programme.artist_budget_minor, 0),
      'contingencyBudgetMinor', coalesce(programme.contingency_budget_minor, 0),
      'draftOfferCommitmentsMinor', 0,
      'sentOfferCommitmentsMinor', 0,
      'acceptedCommitmentsMinor', 0,
      'remainingMinor', coalesce(programme.artist_budget_minor + programme.contingency_budget_minor, 0),
      'potentialApplicationRequestsMinor', 0,
      'headlineBudgetShareBasisPoints', 0,
      'playerArtistBudgetShareBasisPoints', 0,
      'npcArtistBudgetShareBasisPoints', 0
    ),
    'issues', '[]'::jsonb,
    'playerArtistCount', 0,
    'npcArtistCount', 0,
    'playerArtistShareBasisPoints', 0,
    'ready', coalesce(programme.status = 'ready_for_operations', false),
    'canWrite', edition.status NOT IN ('completed', 'cancelled') AND edition.locked_at IS NULL,
    'planningVersion', coalesce(programme.planning_version, 0),
    'updatedAt', programme.updated_at
  )
  FROM public.festival_companies company
  JOIN public.festival_editions_v2 edition
    ON edition.festival_company_id = company.id
   AND edition.id = p_festival_edition_id
  JOIN public.festival_site_plans site
    ON site.festival_edition_id = edition.id
  JOIN public.festival_ticket_plans ticket
    ON ticket.festival_edition_id = edition.id
  LEFT JOIN public.festival_artist_programmes programme
    ON programme.festival_edition_id = edition.id
  WHERE company.id = p_festival_company_id
$$;

