CREATE OR REPLACE FUNCTION public.save_festival_edition_artist_programme(
  p_festival_company_id uuid,
  p_festival_edition_id uuid,
  p_expected_version integer,
  p_programme jsonb,
  p_application_windows jsonb,
  p_idempotency_key uuid,
  p_complete boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor uuid := public._caller_profile_id();
  edition public.festival_editions_v2%ROWTYPE;
  ticket public.festival_ticket_plans%ROWTYPE;
  programme public.festival_artist_programmes%ROWTYPE;
  request public.festival_artist_plan_requests%ROWTYPE;
  payload_hash text;
  application_mode text;
  artist_budget bigint;
  contingency_budget bigint;
  minimum_fame integer;
  maximum_fame integer;
  preferred_genres text[];
  excluded_genres text[];
  application_window_payload jsonb;
  response jsonb;
  old_version integer;
BEGIN
  IF auth.uid() IS NULL
     OR actor IS NULL
     OR NOT public._festival_projection_authorized(
       p_festival_company_id,
       p_festival_edition_id,
       actor
     ) THEN
    RAISE EXCEPTION 'festival_artist_programme_forbidden' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO edition
  FROM public.festival_editions_v2
  WHERE id = p_festival_edition_id
    AND festival_company_id = p_festival_company_id
  FOR UPDATE;
  IF edition.status IN ('completed', 'cancelled') OR edition.locked_at IS NOT NULL THEN
    RAISE EXCEPTION 'festival_artist_programme_locked' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO ticket
  FROM public.festival_ticket_plans
  WHERE festival_edition_id = edition.id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'festival_ticket_plan_incomplete' USING ERRCODE = 'P0001';
  END IF;

  application_mode := p_programme->>'applicationMode';
  artist_budget := coalesce(nullif(p_programme->>'artistBudgetMinor', '')::bigint, 0);
  contingency_budget := coalesce(nullif(p_programme->>'contingencyBudgetMinor', '')::bigint, 0);
  minimum_fame := nullif(p_programme->>'minimumArtistFame', '')::integer;
  maximum_fame := nullif(p_programme->>'maximumArtistFame', '')::integer;
  SELECT coalesce(array_agg(value), '{}'::text[]) INTO preferred_genres
  FROM jsonb_array_elements_text(coalesce(p_programme->'preferredGenres', '[]'::jsonb)) value;
  SELECT coalesce(array_agg(value), '{}'::text[]) INTO excluded_genres
  FROM jsonb_array_elements_text(coalesce(p_programme->'excludedGenres', '[]'::jsonb)) value;

  IF application_mode NOT IN ('closed', 'invite_only', 'applications_only', 'hybrid')
     OR artist_budget < 0
     OR contingency_budget < 0
     OR (maximum_fame IS NOT NULL AND minimum_fame IS NOT NULL AND maximum_fame < minimum_fame) THEN
    RAISE EXCEPTION 'festival_artist_programme_invalid' USING ERRCODE = 'P0001';
  END IF;

  payload_hash := encode(digest(jsonb_build_object(
    'festivalEditionId', edition.id,
    'expectedVersion', p_expected_version,
    'programme', p_programme,
    'applicationWindows', p_application_windows,
    'complete', p_complete
  )::text, 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(
    hashtextextended(edition.id::text || p_idempotency_key::text, 0)
  );

  SELECT * INTO request
  FROM public.festival_artist_plan_requests
  WHERE caller_profile_id = actor
    AND target_entity_id = edition.id
    AND action = 'save_edition_programme'
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF request.payload_hash <> payload_hash THEN
      RAISE EXCEPTION 'festival_artist_idempotency_conflict' USING ERRCODE = 'P0001';
    END IF;
    IF request.status = 'succeeded' THEN
      RETURN request.result;
    END IF;
  ELSE
    INSERT INTO public.festival_artist_plan_requests(
      festival_company_id,
      caller_profile_id,
      target_entity_id,
      action,
      idempotency_key,
      payload_hash
    ) VALUES (
      edition.festival_company_id,
      actor,
      edition.id,
      'save_edition_programme',
      p_idempotency_key,
      payload_hash
    ) RETURNING * INTO request;
  END IF;

  SELECT coalesce(max(planning_version), 0) INTO old_version
FROM public.festival_artist_programmes
WHERE festival_edition_id = edition.id;
IF old_version <> p_expected_version THEN
  RAISE EXCEPTION 'festival_artist_programme_stale' USING ERRCODE = 'P0001';
END IF;

  INSERT INTO public.festival_artist_programmes(
    festival_company_id,
    festival_edition_id,
    festival_ticket_plan_id,
    currency_code,
    application_mode,
    applications_open_at,
    applications_close_at,
    minimum_artist_fame,
    maximum_artist_fame,
    preferred_genres,
    excluded_genres,
    artist_budget_minor,
    contingency_budget_minor,
    minimum_player_artist_share_basis_points,
    status,
    planning_version,
    completed_at
  ) VALUES (
    edition.festival_company_id,
    edition.id,
    ticket.id,
    ticket.currency_code,
    application_mode,
    nullif(p_programme->>'applicationsOpenAt', '')::timestamptz,
    nullif(p_programme->>'applicationsCloseAt', '')::timestamptz,
    minimum_fame,
    maximum_fame,
    preferred_genres,
    excluded_genres,
    artist_budget,
    contingency_budget,
    coalesce(nullif(p_programme->>'minimumPlayerArtistShareBasisPoints', '')::integer, 0),
    CASE WHEN p_complete THEN 'ready_for_operations' ELSE 'applications_configured' END,
    1,
    CASE WHEN p_complete THEN now() ELSE NULL END
  )
  ON CONFLICT (festival_edition_id) WHERE festival_edition_id IS NOT NULL
  DO UPDATE SET
    festival_ticket_plan_id = EXCLUDED.festival_ticket_plan_id,
    currency_code = EXCLUDED.currency_code,
    application_mode = EXCLUDED.application_mode,
    applications_open_at = EXCLUDED.applications_open_at,
    applications_close_at = EXCLUDED.applications_close_at,
    minimum_artist_fame = EXCLUDED.minimum_artist_fame,
    maximum_artist_fame = EXCLUDED.maximum_artist_fame,
    preferred_genres = EXCLUDED.preferred_genres,
    excluded_genres = EXCLUDED.excluded_genres,
    artist_budget_minor = EXCLUDED.artist_budget_minor,
    contingency_budget_minor = EXCLUDED.contingency_budget_minor,
    minimum_player_artist_share_basis_points = EXCLUDED.minimum_player_artist_share_basis_points,
    status = EXCLUDED.status,
    planning_version = public.festival_artist_programmes.planning_version + 1,
    updated_at = now(),
    completed_at = EXCLUDED.completed_at
  RETURNING * INTO programme;

  IF application_mode IN ('applications_only', 'hybrid')
     AND jsonb_array_length(coalesce(p_application_windows, '[]'::jsonb)) > 0 THEN
    application_window_payload := p_application_windows->0;
    INSERT INTO public.festival_artist_application_windows(
      festival_artist_programme_id,
      name,
      opens_at,
      closes_at,
      eligible_artist_type,
      minimum_fame,
      maximum_fame,
      preferred_genres,
      minimum_band_members,
      maximum_band_members,
      target_stage_types,
      maximum_set_minutes,
      active
    ) VALUES (
      programme.id,
      coalesce(nullif(btrim(application_window_payload->>'name'), ''), 'General Festival applications'),
      (application_window_payload->>'opensAt')::timestamptz,
      (application_window_payload->>'closesAt')::timestamptz,
      coalesce(application_window_payload->>'eligibleArtistType', 'player_only'),
      nullif(application_window_payload->>'minimumFame', '')::integer,
      nullif(application_window_payload->>'maximumFame', '')::integer,
      ARRAY(SELECT jsonb_array_elements_text(coalesce(application_window_payload->'preferredGenres', '[]'::jsonb))),
      nullif(application_window_payload->>'minimumBandMembers', '')::integer,
      nullif(application_window_payload->>'maximumBandMembers', '')::integer,
      ARRAY(SELECT jsonb_array_elements_text(coalesce(application_window_payload->'targetStageTypes', '[]'::jsonb))),
      coalesce(nullif(application_window_payload->>'maximumSetMinutes', '')::integer, 60),
      true
    )
    ON CONFLICT (festival_artist_programme_id, name)
    DO UPDATE SET
      opens_at = EXCLUDED.opens_at,
      closes_at = EXCLUDED.closes_at,
      eligible_artist_type = EXCLUDED.eligible_artist_type,
      minimum_fame = EXCLUDED.minimum_fame,
      maximum_fame = EXCLUDED.maximum_fame,
      preferred_genres = EXCLUDED.preferred_genres,
      minimum_band_members = EXCLUDED.minimum_band_members,
      maximum_band_members = EXCLUDED.maximum_band_members,
      target_stage_types = EXCLUDED.target_stage_types,
      maximum_set_minutes = EXCLUDED.maximum_set_minutes,
      active = true,
      version = public.festival_artist_application_windows.version + 1,
      updated_at = now();
  ELSE
    UPDATE public.festival_artist_application_windows
    SET active = false,
        updated_at = now()
    WHERE festival_artist_programme_id = programme.id;
  END IF;

  response := public._festival_edition_artist_programme_result(
    p_festival_company_id,
    p_festival_edition_id
  );
  UPDATE public.festival_artist_plan_requests
  SET status = 'succeeded', result = response, completed_at = now()
  WHERE id = request.id;
  RETURN response;
END;
$$;

-- Backfill every complete, editable annual Festival. Existing manual rows are retained.
DO $$
DECLARE
  edition record;
BEGIN
  FOR edition IN
    SELECT id, festival_company_id
    FROM public.festival_editions_v2
    WHERE status NOT IN ('cancelled', 'completed')
      AND locked_at IS NULL
      AND starts_on IS NOT NULL
      AND ends_on IS NOT NULL
      AND city_id IS NOT NULL
      AND site_type IS NOT NULL
      AND festival_scale IS NOT NULL
      AND coalesce(expected_capacity, 0) > 0
  LOOP
    PERFORM public.materialize_festival_edition_foundations(
      edition.festival_company_id,
      edition.id
    );
  END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public._festival_projection_currency(uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_projection_authorized(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_projection_forecast(date, date, integer, bigint, integer, integer, integer) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.materialize_festival_edition_foundations(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_edition_foundation_trigger() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_edition_site_plan_result(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_edition_ticket_plan_result(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._festival_edition_artist_programme_result(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.get_festival_edition_site_plan(uuid, uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.get_festival_edition_ticket_plan(uuid, uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.save_festival_edition_ticket_plan(uuid, uuid, integer, jsonb, jsonb, jsonb, jsonb, uuid, boolean) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.get_festival_edition_artist_programme(uuid, uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.save_festival_edition_artist_programme(uuid, uuid, integer, jsonb, jsonb, uuid, boolean) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.get_festival_edition_site_plan(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_edition_ticket_plan(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.save_festival_edition_ticket_plan(uuid, uuid, integer, jsonb, jsonb, jsonb, jsonb, uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_edition_artist_programme(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.save_festival_edition_artist_programme(uuid, uuid, integer, jsonb, jsonb, uuid, boolean) TO authenticated;

COMMENT ON FUNCTION public.materialize_festival_edition_foundations(uuid, uuid) IS
  'Creates or refreshes hidden, exact-edition site, stage and ticket foundations from the simplified annual plan without overwriting manually-owned plans.';
COMMENT ON FUNCTION public.save_festival_edition_ticket_plan(uuid, uuid, integer, jsonb, jsonb, jsonb, jsonb, uuid, boolean) IS
  'Exact-edition simple ticket choice save. Detailed products, releases, allocations and forecasts remain server generated.';
COMMENT ON FUNCTION public.save_festival_edition_artist_programme(uuid, uuid, integer, jsonb, jsonb, uuid, boolean) IS
  'Exact-edition simple line-up strategy and budget save.';

NOTIFY pgrst, 'reload schema';
